/// Host function behind the require() loader's module-source read.
///
/// Java `JobJavaScriptBridge.loadModule` parity (gh-369): the loader is a
/// HOST primitive reading via `loadJavaScriptCode` — direct host IO that
/// never consults the `FileTools` sandbox (that governs agent tool calls).
/// The loader only reads paths it resolved itself from the current script
/// directory / module spec, so it is host-trusted machinery: pack modules
/// under `~/.dmtools/packs` load regardless of the working-dir containment
/// or `DMTOOLS_FILE_READ_ALLOWED_PATHS` (live: v0.1.41 broke every
/// pack-internal require otherwise — the 21:49Z SM tick died on
/// `sm_github-0.1.36/js/configLoader.js`).
///
/// Returns the file content as a plain JSON string (the C bridge unmarshals
/// it back to a JS string), or JS `null` when the file cannot be read —
/// the same contract the `file_read` host gives, so the require prelude's
/// 'JavaScript file not found' path is unchanged. No call logging: this is
/// not a tool call (nothing agent-visible happens here); the subsequent
/// module eval is the observable event.
library;

import 'dart:convert';
import 'dart:io';

/// Handles `__loaderFileRead(path)` calls from the require prelude.
///
/// The argument arrives JSON-marshaled through the FFI bridge: a single
/// string argument as the JSON string itself, an object as `{"path": …}`
/// (mirroring how [ToolBridge] decodes `file_read` calls).
String loaderReadHost(String argsJson) {
  dynamic parsed;
  try {
    parsed = jsonDecode(argsJson);
  } on FormatException {
    parsed = null;
  }
  String? path;
  if (parsed is String) path = parsed;
  if (parsed is Map) path = parsed['path'] as String?;
  if (path == null) return 'null';
  try {
    return jsonEncode(File(path).readAsStringSync());
  } catch (_) {
    return 'null';
  }
}

/// The JS bootstrap wiring the public host-function globals.
const String hostFunctionsBootstrap = '''
(function() {
    function __unwrapHostError(result) {
        if (result !== null && result !== undefined &&
                typeof result === 'object' &&
                result.__jsError !== undefined) {
            throw new Error(result.__jsError);
        }
        return result;
    }
    globalThis.executeToolViaJava = function() {
        return __unwrapHostError(
            __executeToolViaJavaHost.apply(null, arguments));
    };
    globalThis.file_read = function() {
        return __unwrapHostError(__fileReadHost.apply(null, arguments));
    };
    // Host-private: the require() loader's own source read. Deliberately
    // NOT the sandboxed file_read — Java `loadModule` reads module sources
    // via `loadJavaScriptCode` (direct host IO); the FileTools sandbox
    // governs agent tool calls only. Never referenced by agent code.
    globalThis.__loaderFileRead = function() {
        return __unwrapHostError(__loaderReadHost.apply(null, arguments));
    };
    globalThis.set_env_variable = function() {
        return __unwrapHostError(
            __setEnvVariableHost.apply(null, arguments));
    };
})();
''';

/// CommonJS `require()` loader — JS bootstrap prelude for [QuickjsRuntime].
///
/// Dart port of the Java `JobJavaScriptBridge` module loader
/// (`RequireProxy` / `loadModule` / `resolveModulePath` /
/// `setCurrentScriptDirectory`, dmtools-core
/// `job/JobJavaScriptBridge.java`).
///
/// The FFI host functions marshal results through JSON, so a host-side
/// `require` could never return module exports containing functions. The
/// loader therefore lives entirely in JS: it reads module sources through
/// the host-private `__loaderFileRead` primitive (direct host IO, Java
/// `loadJavaScriptCode` parity — deliberately not the sandboxed
/// `file_read`, whose containment would block pack-internal modules,
/// gh-369) and evaluates them with `eval()`, so real JS objects
/// (functions included) flow between modules.
///
/// Semantics ported 1:1 from Java:
/// - `./x` / `../x` resolve against the current script directory, which is
///   saved/restored around each module eval (`try`/`finally`) and updated to
///   the module's own directory first, so relative requires inside modules
///   resolve correctly.
/// - Module cache is keyed by resolved path; a placeholder object is cached
///   **before** eval so circular requires terminate, and is replaced by the
///   real exports afterwards.
/// - Module code runs wrapped exactly like Java:
///   `(function() { var module = { exports: {} }; var exports =
///   module.exports; <CODE> return module.exports; })()`.
/// - On load failure the cache entry is removed and
///   `Failed to require module: <path>` is thrown; the cause message keeps
///   the Java `JavaScript file not found` substring visible.
/// - `require()` argument validation:
///   `require() expects exactly one argument (module path)`.
///
/// Known deviation: Java's `loadModule` re-enters `loadJavaScriptCode`, so a
/// require argument that is itself a URL fetches remotely; the JS prelude
/// has no synchronous fetch host function and only reads files.
library;

import 'package:quickjs_runtime/quickjs_runtime.dart';

/// Installs `globalThis.require` and `globalThis.__setScriptDirectory` on
/// [runtime].
///
/// Must run before the user script is evaluated; `require` only invokes
/// `file_read` at script runtime, so the host function may be registered
/// later.
void installRequireLoader(QuickjsRuntime runtime) {
  runtime.eval(_requireLoaderBootstrap, filename: '<require_loader>');
}

/// The loader bootstrap evaluated on the runtime.
///
/// State (`currentScriptDirectory`, `moduleCache`) lives in the closure, so
/// repeated installs each get a fresh cache — matching the Java bridge,
/// whose cache is cleared on `close()`.
const String _requireLoaderBootstrap = '''
(function() {
    var currentScriptDirectory = '';
    var moduleCache = {};

    function scriptDirOf(path) {
        if (typeof path !== 'string' || path.indexOf('/') === -1) {
            return '';
        }
        var lastSlash = path.lastIndexOf('/');
        return lastSlash > 0 ? path.substring(0, lastSlash) : '';
    }

    function normalizePath(path) {
        var absolute = path.charAt(0) === '/';
        var segments = path.split('/');
        var out = [];
        for (var i = 0; i < segments.length; i++) {
            var segment = segments[i];
            if (segment === '' || segment === '.') continue;
            if (segment === '..') {
                if (out.length > 0 && out[out.length - 1] !== '..') {
                    out.pop();
                } else if (!absolute) {
                    out.push('..');
                }
                continue;
            }
            out.push(segment);
        }
        var joined = out.join('/');
        return absolute ? '/' + joined : joined;
    }

    function resolveModulePath(modulePath) {
        if (modulePath.indexOf('./') === 0 ||
                modulePath.indexOf('../') === 0) {
            if (currentScriptDirectory) {
                return normalizePath(
                    currentScriptDirectory + '/' + modulePath);
            }
        }
        return modulePath;
    }

    function readModuleCode(resolvedPath) {
        // Host-private direct read (Java loadJavaScriptCode parity) — NOT
        // the sandboxed file_read: module sources are host-trusted loader
        // input, so packs under ~/.dmtools load regardless of the
        // working-dir containment (gh-369).
        var content = __loaderFileRead(resolvedPath);
        if (content === null || content === undefined) {
            throw new Error('JavaScript file not found in resources or ' +
                'filesystem: ' + resolvedPath);
        }
        return content;
    }

    function wrapModuleCode(code) {
        return '(function() { var module = { exports: {} }; ' +
            'var exports = module.exports;\\n' + code +
            '\\nreturn module.exports; })()';
    }

    function loadModule(modulePath) {
        var resolvedPath = resolveModulePath(modulePath);
        if (Object.prototype.hasOwnProperty.call(
                moduleCache, resolvedPath)) {
            return moduleCache[resolvedPath];
        }
        var savedScriptDirectory = currentScriptDirectory;
        // Placeholder cached before eval: circular requires get it and
        // terminate instead of recursing (Java loadModule parity).
        var placeholder = {};
        moduleCache[resolvedPath] = placeholder;
        try {
            currentScriptDirectory = scriptDirOf(resolvedPath);
            var moduleExports =
                eval(wrapModuleCode(readModuleCode(resolvedPath)));
            moduleCache[resolvedPath] = moduleExports;
            return moduleExports;
        } catch (e) {
            delete moduleCache[resolvedPath];
            var cause = (e && e.message) ? e.message : String(e);
            throw new Error('Failed to require module: ' + modulePath +
                ' (' + cause + ')');
        } finally {
            currentScriptDirectory = savedScriptDirectory;
        }
    }

    globalThis.require = function(modulePath) {
        if (arguments.length !== 1) {
            throw new Error(
                'require() expects exactly one argument (module path)');
        }
        return loadModule(modulePath);
    };

    globalThis.__setScriptDirectory = function(path) {
        currentScriptDirectory = scriptDirOf(path);
    };
})();
''';

