  /// main engine composed — JSON round-tripped); the composition fields
  /// are ignored.
  const EngineContext.direct(Map<String, dynamic> params)
      : directParams = params,
        jobParams = const {},
        ticket = null,
        contextParams = null,
        extraGlobals = null;

  /// Injected as `params.jobParams` (ignored in [EngineContext.direct]).
