/// stdout, `warn/error` to stderr, worker prefix preserved.
NodeCompatHandle? _installNodeCompatIfEnabled(
  QuickjsRuntime rt,
  EngineSpec spec,
) {
  final ctx = spec.context;
  final jobParams = (ctx.directParams?['jobParams'] as Map?) ?? ctx.jobParams;
