          ),
        ),
      );
    } finally {
      dir.deleteSync(recursive: true);
    }
  });
}

void _requireArgumentValidation() {
  for (final (label, call) in [
    ('zero arguments', 'require()'),
    ('two arguments', "require('./a.js', 'b')"),
